export function installStudyBackup(store){
 const section=document.createElement('section');section.className='backup-tools';section.innerHTML='<h2>Çalışma yedeği</h2><p>Favoriler, kişisel notlar ve son görünüm. Yedek cihazında kalır.</p><button id="exportStudy">Yedeği hazırla</button><button id="importStudy">Yedeği geri yükle</button>';
 document.querySelector('#workspace-saved').append(section);
 const dialog=document.createElement('dialog');dialog.id='backupDialog';dialog.innerHTML='<button class="dialog-close" aria-label="Yedek penceresini kapat">×</button><h2>Çalışma yedeğini birleştir</h2><p>Yedek JSON metnini yapıştır. Mevcut notların korunur; aynı yapıya ait farklı not varsa cihazındaki not önceliklidir. İnceleyip Birleştir düğmesine dokunana kadar hiçbir kayıt değişmez.</p><label for="backupText">Yedek JSON</label><textarea id="backupText" rows="9" maxlength="2000000" spellcheck="false"></textarea><button id="mergeStudy">Birleştir ve kaydet</button><p id="backupStatus" role="status"></p>';document.body.append(dialog);
 dialog.querySelector('.dialog-close').onclick=()=>dialog.close();document.querySelector('#importStudy').onclick=()=>{dialog.querySelector('#backupStatus').textContent='';dialog.showModal();};
 const exportDialog=document.createElement('dialog');exportDialog.id='backupExportDialog';exportDialog.innerHTML='<button class="dialog-close" aria-label="Hazır yedeği kapat">×</button><h2>Çalışma yedeğin hazır</h2><p>JSON dosyası olarak indir veya metni kopyalayıp cihazında sakla. Bu yedek kişisel notlarını içerir.</p><label for="backupExportText">Yedek JSON</label><textarea id="backupExportText" rows="9" readonly spellcheck="false"></textarea><button id="downloadStudyBackup">Dosya olarak indir</button><button id="copyStudyBackup">Metni kopyala</button><p id="backupExportStatus" role="status"></p>';document.body.append(exportDialog);
 const exportText=exportDialog.querySelector('#backupExportText'),exportStatus=exportDialog.querySelector('#backupExportStatus');exportDialog.querySelector('.dialog-close').onclick=()=>exportDialog.close();
 document.querySelector('#exportStudy').onclick=()=>{exportText.value=store.exportBackup();exportStatus.textContent='İndirmenin desteklenmediği tarayıcılarda metni kopyalayabilirsin.';exportDialog.showModal();};
 exportDialog.querySelector('#downloadStudyBackup').onclick=()=>{try{const blob=new Blob([exportText.value],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='anatomi-calisma-yedegi-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);exportStatus.textContent='Dosya isteği başlatıldı. İndirmeler listesinde görünmüyorsa metni kopyalayarak sakla.';}catch{exportStatus.textContent='Dosya indirme açılamadı. Yedek metnini kopyalayarak saklayabilirsin.';}};
 exportDialog.querySelector('#copyStudyBackup').onclick=async()=>{try{await navigator.clipboard.writeText(exportText.value);exportStatus.textContent='Yedek metni panoya kopyalandı.';}catch{exportText.focus();exportText.select();exportStatus.textContent='Metin seçildi. Tarayıcının Kopyala komutunu kullanabilirsin.';}};
 dialog.querySelector('#mergeStudy').onclick=()=>{const status=dialog.querySelector('#backupStatus');try{const result=store.mergeBackup(dialog.querySelector('#backupText').value);status.textContent='Yedek birleştirildi. '+result.favorites+' favori ve '+result.notes+' not okundu.'+(result.conflicts?' '+result.conflicts+' farklı notta cihazındaki kayıt korundu.':'');}catch(e){status.textContent=e.message;}};
}
